-- OWNED_BY: generic. Signed human schedules and source-linked administration; no dose recommendations.
BEGIN;
CREATE TABLE rs_mar_plans(schedule_id bigint PRIMARY KEY REFERENCES mar_jadwal(id),tenant_id uuid NOT NULL REFERENCES tenants(id),rx_item_id bigint NOT NULL REFERENCES prescription_items(id),dispense_item_id bigint NOT NULL REFERENCES pharmacy_dispense_items(id),clinical_record_id bigint NOT NULL UNIQUE REFERENCES rs_clinical_records(id),policy_snapshot jsonb NOT NULL,quantity_per_dose numeric NOT NULL CHECK(quantity_per_dose>0),due_times jsonb NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','verified','stopped')),created_by uuid NOT NULL,reviewed_by uuid,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);
CREATE UNIQUE INDEX rs_mar_one_live_plan ON rs_mar_plans(rx_item_id,dispense_item_id) WHERE state IN ('draft','verified');
CREATE TABLE rs_mar_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),schedule_id bigint NOT NULL REFERENCES rs_mar_plans(schedule_id),due_at timestamptz NOT NULL,outcome text NOT NULL CHECK(outcome IN ('Diberikan','Ditunda','Ditolak Pasien','Dilewati','Dihentikan')),source_mar_id bigint NOT NULL REFERENCES mar_pemberian(id),given_at timestamptz,recorded_by uuid NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),amendment_of bigint UNIQUE REFERENCES rs_mar_events(id),correction_record_id bigint REFERENCES rs_clinical_records(id));
CREATE UNIQUE INDEX rs_mar_initial_event ON rs_mar_events(schedule_id,due_at) WHERE amendment_of IS NULL;
CREATE TABLE rs_medication_custody_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),dispense_item_id bigint NOT NULL REFERENCES pharmacy_dispense_items(id),kind text NOT NULL CHECK(kind IN ('return','waste','take_home')),quantity numeric NOT NULL CHECK(quantity>0),state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','posting','posted','rejected')),evidence jsonb NOT NULL,created_by uuid NOT NULL,reviewed_by uuid,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,version integer NOT NULL DEFAULT 1,reason text NOT NULL,source_ledger_id bigint REFERENCES pharmacy_stock_ledger(id),source_charge_id bigint REFERENCES inpatient_charges(id));
CREATE FUNCTION rs_medication_custody_used(p_dispense_item bigint) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT coalesce((SELECT sum(p.quantity_per_dose) FROM rs_mar_plans p JOIN rs_mar_events e ON e.schedule_id=p.schedule_id WHERE p.dispense_item_id=p_dispense_item AND e.outcome='Diberikan' AND NOT EXISTS(SELECT 1 FROM rs_mar_events successor WHERE successor.amendment_of=e.id)),0)+coalesce((SELECT sum(quantity) FROM rs_medication_custody_events WHERE dispense_item_id=p_dispense_item AND state='posted'),0)
$$;
ALTER FUNCTION mar_catat(bigint,date,text,text,text,text,text) RENAME TO mar_catat_before_rs_pharmacy;
REVOKE ALL ON FUNCTION mar_catat_before_rs_pharmacy(bigint,date,text,text,text,text,text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION rs_mar_command(p_action text,p_data jsonb,p_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE t uuid:=current_tenant_id();a uuid;r rs_pharmacy_requests;ctx rs_prescription_contexts;adm admissions;plan rs_mar_plans;schedule mar_jadwal;item prescription_items;dispensed pharmacy_dispense_items;record rs_clinical_records;policy ops_policy_versions;event rs_mar_events;prior rs_mar_events;
 input_value jsonb:=jsonb_build_object('mar_action',p_action,'data',p_data);result_value jsonb;source_result jsonb;before_value jsonb;dates_value jsonb;due_value timestamptz;quantity_value numeric;source_id bigint;selected_date text;identity_field text;identity_value jsonb;correction rs_clinical_records;correction_policy ops_policy_versions;
BEGIN
 a:=ops_actor(ARRAY['dokter','doctor','pharmacist','apoteker','nurse','perawat']);
 IF p_action IS NULL OR p_action NOT IN ('schedule','verify','record','stop') OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR p_key IS NULL OR length(p_key) NOT BETWEEN 8 AND 150 OR coalesce(length(trim(p_data->>'reason')),0)<5 THEN RAISE EXCEPTION 'Action/input/key/alasan wajib';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(t::text||p_key,0));SELECT * INTO r FROM rs_pharmacy_requests WHERE tenant_id=t AND request_key=p_key;
 IF FOUND THEN IF r.actor_id<>a OR r.input<>input_value THEN RAISE EXCEPTION 'Retry actor/input berbeda';END IF;RETURN r.result;END IF;
 IF p_action='schedule' THEN
  SELECT * INTO record FROM rs_clinical_records WHERE id=(p_data->>'clinical_record_id')::bigint AND tenant_id=t AND signed_at IS NOT NULL;
  SELECT * INTO item FROM prescription_items WHERE id=(record.form_values->>'rx_item_id')::bigint;
 ELSE SELECT * INTO plan FROM rs_mar_plans WHERE schedule_id=(p_data->>'schedule_id')::bigint AND tenant_id=t;SELECT * INTO item FROM prescription_items WHERE id=plan.rx_item_id;END IF;
 SELECT * INTO ctx FROM rs_prescription_contexts WHERE rx_id=item.rx_id AND tenant_id=t;IF ctx.rx_id IS NULL THEN RAISE EXCEPTION 'Jadwal/resep/clinical record bukan milik tenant';END IF;
 PERFORM 1 FROM inpatient_stays WHERE admission_id=ctx.admission_id AND tenant_id=t AND status='Dirawat' ORDER BY id FOR UPDATE;SELECT * INTO adm FROM admissions WHERE id=ctx.admission_id AND tenant_id=t FOR UPDATE;PERFORM rs_pharmacy_assert_encounter(adm.id,ctx.episode_id);
 PERFORM set_config('TimeZone',ctx.reconciliation_snapshot->>'timezone',true);PERFORM ops_assert_permission('rs-ward-pharmacy','clinical.pharmacy.mar.'||p_action);
 IF plan.schedule_id IS NOT NULL THEN SELECT * INTO plan FROM rs_mar_plans WHERE schedule_id=plan.schedule_id FOR UPDATE;SELECT * INTO schedule FROM mar_jadwal WHERE id=plan.schedule_id FOR UPDATE;END IF;before_value:=to_jsonb(plan);
 IF p_action='schedule' THEN
  PERFORM ops_actor(ARRAY['dokter','doctor']);SELECT * INTO policy FROM ops_policy_versions WHERE id=record.policy_id AND tenant_id=t;
  IF record.admission_id IS DISTINCT FROM adm.id OR policy.kind<>'clinical_template' OR policy.scope<>'rs-ward-pharmacy' OR policy.payload->>'purpose' IS DISTINCT FROM 'medication_schedule' OR policy.payload->>'timezone' IS DISTINCT FROM ctx.reconciliation_snapshot->>'timezone' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(policy.payload->'signer_roles') role_name WHERE role_name NOT IN ('dokter','doctor')) OR EXISTS(SELECT 1 FROM rs_clinical_records WHERE amendment_of=record.id AND signed_at IS NOT NULL) THEN RAISE EXCEPTION 'Jadwal dari record dokter signed dan SOP yang sesuai wajib';END IF;
  SELECT * INTO dispensed FROM pharmacy_dispense_items WHERE id=(record.form_values->>'dispense_item_id')::bigint AND rx_item_id=item.id;
  IF dispensed.id IS NULL OR NOT EXISTS(SELECT 1 FROM rs_prescription_verifications WHERE rx_id=item.rx_id AND tenant_id=t) THEN RAISE EXCEPTION 'Item dispensing aktual dan verifikasi apoteker wajib';END IF;
  IF jsonb_typeof(policy.payload->'early_minutes') IS DISTINCT FROM 'number' OR jsonb_typeof(policy.payload->'late_minutes') IS DISTINCT FROM 'number' OR (policy.payload->>'early_minutes')::numeric<0 OR (policy.payload->>'late_minutes')::numeric<0 OR jsonb_typeof(policy.payload->'allow_fractional_stock_units') IS DISTINCT FROM 'boolean' OR jsonb_typeof(policy.payload->'administration_qty_decimals') IS DISTINCT FROM 'number' OR (policy.payload->>'administration_qty_decimals')::integer NOT BETWEEN 0 AND 6 OR jsonb_typeof(policy.payload->'identity_fields') IS DISTINCT FROM 'array' OR jsonb_array_length(policy.payload->'identity_fields')<2 THEN RAISE EXCEPTION 'Window/precision/fraction/identitas SOP wajib eksplisit';END IF;
  FOR identity_field IN SELECT value FROM jsonb_array_elements_text(policy.payload->'identity_fields') LOOP IF identity_field NOT IN ('mr_number','patient_name','visit_number','patient_dob') THEN RAISE EXCEPTION 'Field verifikasi identitas tidak didukung';END IF;END LOOP;
  IF (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(policy.payload->'identity_fields'))<>jsonb_array_length(policy.payload->'identity_fields') THEN RAISE EXCEPTION 'Dua identitas harus berbeda';END IF;
  quantity_value:=(record.form_values->>'quantity_stock_units')::numeric;
  IF quantity_value IS NULL OR quantity_value<=0 OR quantity_value<>round(quantity_value,(policy.payload->>'administration_qty_decimals')::integer) OR policy.payload->'allow_fractional_stock_units'='false'::jsonb AND mod(quantity_value,(rs_pharmacy_active_binding(item.drug_id)).qty_step)<>0 THEN RAISE EXCEPTION 'Quantity dosis stock-unit tidak sesuai SOP';END IF;
  IF EXISTS(SELECT 1 FROM unnest(string_to_array(record.form_values->>'due_times',E'\n')) slot(value) WHERE trim(value)<>'' AND trim(value)!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?([Zz]|[+-][0-9]{2}:[0-9]{2})$') THEN RAISE EXCEPTION 'Slot jadwal wajib ISO 8601 dengan offset timezone eksplisit';END IF;
  SELECT coalesce(jsonb_agg(d ORDER BY d),'[]') INTO dates_value FROM (SELECT trim(value)::timestamptz d FROM unnest(string_to_array(record.form_values->>'due_times',E'\n')) value WHERE trim(value)<>'') dates;
  IF jsonb_array_length(dates_value) NOT BETWEEN 1 AND 500 OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(dates_value))<>jsonb_array_length(dates_value) OR quantity_value*jsonb_array_length(dates_value)>dispensed.qty-rs_medication_custody_used(dispensed.id) THEN RAISE EXCEPTION 'Jadwal eksplisit unik dan quantity tidak boleh melebihi custody sumber';END IF;
  INSERT INTO mar_jadwal(admission_id,stay_id,patient_name,mr_number,prescription_id,nama_obat,dosis,rute,frekuensi,jam_pemberian,mulai_tgl,sampai_tgl,instruksi,diresepkan_oleh,status)
  VALUES(adm.id,(SELECT id FROM inpatient_stays WHERE admission_id=adm.id AND status='Dirawat'),adm.patient_name,adm.mr_number,item.rx_id,item.drug_name,item.dose,record.form_values->>'route',item.frequency,dates_value,(dates_value->>0)::timestamptz::date,(dates_value->>(jsonb_array_length(dates_value)-1))::timestamptz::date,item.instruction,current_app_name(),'Draf') RETURNING * INTO schedule;
  INSERT INTO rs_mar_plans(schedule_id,tenant_id,rx_item_id,dispense_item_id,clinical_record_id,policy_snapshot,quantity_per_dose,due_times,created_by) VALUES(schedule.id,t,item.id,dispensed.id,record.id,policy.payload,quantity_value,dates_value,a) RETURNING * INTO plan;result_value:=to_jsonb(plan);
 ELSIF p_action='verify' THEN
  PERFORM ops_actor(ARRAY['pharmacist','apoteker']);SELECT * INTO record FROM rs_clinical_records WHERE id=plan.clinical_record_id;
  IF plan.state<>'draft' OR record.signed_by=a OR EXISTS(SELECT 1 FROM rs_clinical_records WHERE amendment_of=record.id AND signed_at IS NOT NULL) THEN RAISE EXCEPTION 'Jadwal dokter harus diverifikasi apoteker berbeda dan belum diamend';END IF;
  IF coalesce(length(trim(p_data->>'dose_schedule_review')),0)<5 THEN RAISE EXCEPTION 'Review quantity/route/waktu profesional wajib';END IF;
  UPDATE mar_jadwal SET status='Aktif',updated_at=now() WHERE id=plan.schedule_id;UPDATE rs_mar_plans SET state='verified',reviewed_by=a,reviewed_at=now() WHERE schedule_id=plan.schedule_id RETURNING * INTO plan;result_value:=to_jsonb(plan);
 ELSIF p_action='record' THEN
  PERFORM ops_actor(ARRAY['nurse','perawat']);due_value:=(p_data->>'due_at')::timestamptz;
  IF plan.state<>'verified' OR schedule.status<>'Aktif' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(plan.due_times) d(value) WHERE d.value::timestamptz=due_value) OR p_data->>'outcome' IS NULL OR p_data->>'outcome' NOT IN ('Diberikan','Ditunda','Ditolak Pasien','Dilewati','Dihentikan') THEN RAISE EXCEPTION 'Jadwal aktif/slot/outcome tidak valid';END IF;
  FOR identity_field IN SELECT value FROM jsonb_array_elements_text(plan.policy_snapshot->'identity_fields') LOOP identity_value:=to_jsonb(adm)->identity_field;IF identity_value IS NULL OR identity_value='null'::jsonb OR p_data->'patient_verification'->identity_field IS DISTINCT FROM identity_value THEN RAISE EXCEPTION 'Verifikasi identitas pasien tidak cocok';END IF;END LOOP;
  SELECT * INTO prior FROM rs_mar_events e WHERE schedule_id=plan.schedule_id AND due_at=due_value AND NOT EXISTS(SELECT 1 FROM rs_mar_events next WHERE next.amendment_of=e.id) FOR UPDATE;
  IF prior.id IS NOT NULL AND prior.id IS DISTINCT FROM (p_data->>'amendment_of')::bigint OR prior.id IS NULL AND p_data->>'amendment_of' IS NOT NULL THEN RAISE EXCEPTION 'Slot sudah tercatat; amendment harus mengacu head terbaru';END IF;
  IF prior.outcome='Diberikan' THEN
   SELECT * INTO correction FROM rs_clinical_records WHERE id=(p_data->>'correction_record_id')::bigint AND tenant_id=t AND admission_id=adm.id AND signed_at IS NOT NULL;SELECT * INTO correction_policy FROM ops_policy_versions WHERE id=correction.policy_id;
   IF correction.id IS NULL OR correction.signed_by=prior.recorded_by OR correction.created_at<prior.created_at OR EXISTS(SELECT 1 FROM rs_clinical_records amended WHERE amended.amendment_of=correction.id AND amended.signed_at IS NOT NULL) OR correction_policy.scope<>'rs-ward-pharmacy' OR correction_policy.payload->>'purpose' IS DISTINCT FROM 'medication_administration_correction' OR (correction.form_values->>'source_event_id')::bigint IS DISTINCT FROM prior.id OR correction.form_values->>'new_outcome' IS DISTINCT FROM p_data->>'outcome' THEN RAISE EXCEPTION 'Koreksi given memerlukan record klinis independen signed';END IF;
  END IF;
  IF p_data->>'outcome'='Diberikan' THEN
   IF clock_timestamp()<due_value-make_interval(secs => 60*(plan.policy_snapshot->>'early_minutes')::double precision) OR clock_timestamp()>due_value+make_interval(secs => 60*(plan.policy_snapshot->>'late_minutes')::double precision) THEN RAISE EXCEPTION 'Pemberian di luar window SOP; perlu jadwal dokter yang diamend';END IF;
   SELECT * INTO dispensed FROM pharmacy_dispense_items WHERE id=plan.dispense_item_id FOR UPDATE;
   IF rs_medication_custody_used(dispensed.id)+(CASE WHEN prior.outcome='Diberikan' THEN 0 ELSE plan.quantity_per_dose END)>dispensed.qty THEN RAISE EXCEPTION 'Custody medication tidak cukup';END IF;
  END IF;
  IF prior.id IS NULL THEN
   source_result:=mar_catat_before_rs_pharmacy(plan.schedule_id,due_value::date,to_char(due_value,'HH24:MI:SS OF'),p_data->>'outcome',current_app_name(),p_data->>'reason',p_data->>'note');IF source_result->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Source MAR gagal: %',source_result;END IF;source_id:=(source_result->>'id')::bigint;
  ELSE source_id:=prior.source_mar_id;END IF;
  INSERT INTO rs_mar_events(tenant_id,schedule_id,due_at,outcome,source_mar_id,given_at,recorded_by,reason,amendment_of,correction_record_id)
  VALUES(t,plan.schedule_id,due_value,p_data->>'outcome',source_id,CASE WHEN p_data->>'outcome'='Diberikan' THEN clock_timestamp() END,a,p_data->>'reason',prior.id,correction.id) RETURNING * INTO event;result_value:=to_jsonb(event);
 ELSIF p_action='stop' THEN
  PERFORM ops_actor(ARRAY['dokter','doctor']);IF plan.state NOT IN ('draft','verified') THEN RAISE EXCEPTION 'Jadwal sudah stopped';END IF;
  UPDATE mar_jadwal SET status='Dihentikan',alasan_henti=p_data->>'reason',updated_at=now() WHERE id=plan.schedule_id;UPDATE rs_mar_plans SET state='stopped' WHERE schedule_id=plan.schedule_id RETURNING * INTO plan;result_value:=to_jsonb(plan);
 END IF;
 INSERT INTO rs_pharmacy_events(tenant_id,actor_id,action,ref_id,reason,before_row,after_row) VALUES(t,a,'mar.'||p_action,plan.schedule_id,p_data->>'reason',before_value,result_value);INSERT INTO rs_pharmacy_requests VALUES(t,p_key,a,input_value,result_value);RETURN result_value;
END $$;
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['rs_mar_plans','rs_mar_events','rs_medication_custody_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('REVOKE ALL ON %I FROM PUBLIC,anon,authenticated',n);END LOOP;END $$;
CREATE POLICY rs_mar_plan_read ON rs_mar_plans FOR SELECT TO authenticated USING(tenant_id=current_tenant_id() AND rs_can_read('rs-ward-pharmacy'));
CREATE POLICY rs_mar_event_read ON rs_mar_events FOR SELECT TO authenticated USING(tenant_id=current_tenant_id() AND rs_can_read('rs-ward-pharmacy'));GRANT SELECT ON rs_mar_plans,rs_mar_events TO authenticated;
CREATE TRIGGER rs_mar_original_event_immutable BEFORE UPDATE OR DELETE ON rs_mar_events FOR EACH ROW EXECUTE FUNCTION rs_pharmacy_signed_metadata_guard();
REVOKE INSERT,UPDATE,DELETE,TRUNCATE ON mar_jadwal,mar_pemberian FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION rs_medication_custody_used(bigint),rs_mar_command(text,jsonb,text) FROM PUBLIC,anon;REVOKE ALL ON FUNCTION rs_medication_custody_used(bigint) FROM authenticated;GRANT EXECUTE ON FUNCTION rs_mar_command(text,jsonb,text) TO authenticated;
COMMIT;
